import type { Timestamp } from 'firebase/firestore'

export type ConfidenceLabel = 'High confidence' | 'Moderate confidence' | 'Low confidence'

export interface TimeSlotSummary {
  summaryText: string
  freshnessText: string
  confidenceLabel: ConfidenceLabel
  comfortScore: number // e.g. 0-100
  topObservations: string[]
}

/**
 * AI & Aggregated Area Summary document stored at areaSummaries/{areaId}
 *
 * Generated by the generateAreaSummary Cloud Function using Gemini.
 * Write-protected against direct client modification.
 */
export interface AreaSummaryDoc {
  areaId: string
  summaryText: string
  summary?: string // Alias for summaryText
  freshnessText: string
  freshness?: string // Alias for freshnessText
  confidenceLabel: ConfidenceLabel
  confidence?: string // Alias for confidenceLabel
  generatedAt: Timestamp
  sourceReportCount: number
  modelVersion: string // e.g. 'gemini-1.5-flash'

  // Time-of-day contextual breakdowns
  day: TimeSlotSummary
  evening: TimeSlotSummary
  night: TimeSlotSummary
}
